<section class="page-hero"><div class="container py-5"><span class="eyebrow text-warning">CATALOGUE</span><h1 class="display-4 fw-bold text-white">Trouvez votre activité</h1><p class="text-white-50">Filtrez par sport, niveau, prix ou lieu.</p></div></section><main class="container py-5"><form class="filter-panel row g-3 mb-5"><div class="col-lg-4"><label class="form-label">Recherche</label><input class="form-control" name="q" value="<?=e($_GET['q']??'')?>" placeholder="Activité ou ville"></div><div class="col-md-4 col-lg-3"><label class="form-label">Sport</label><select class="form-select" name="category"><option value="">Tous</option><?php foreach($categories as $c): ?><option value="<?=e($c['slug'])?>" <?=($_GET['category']??'')===$c['slug']?'selected':''?>><?=e($c['name'])?></option><?php endforeach; ?></select></div><div class="col-md-4 col-lg-2"><label class="form-label">Niveau</label><select class="form-select" name="level"><option value="">Tous</option><?php foreach(['Débutant','Intermédiaire','Avancé'] as $l): ?><option <?=($_GET['level']??'')===$l?'selected':''?>><?=$l?></option><?php endforeach; ?></select></div><div class="col-md-4 col-lg-2"><label class="form-label">Prix max.</label><input type="number" class="form-control" name="max_price" value="<?=e($_GET['max_price']??'')?>" min="0"></div><div class="col-lg-1 d-flex align-items-end"><button class="btn btn-accent w-100"><i class="bi bi-funnel"></i></button></div></form><div class="row g-4"><?php foreach($activities as $a): ?><div class="col-md-6 col-lg-4"><article class="activity-card h-100"><div class="activity-img" style="background-image:url('<?=e($a['image_url'])?>')"><span class="badge bg-light text-dark"><?=e($a['category'])?></span><span class="price"><?=number_format($a['price'],0)?>€</span></div><div class="p-4"><div class="small text-secondary"><i class="bi bi-geo-alt"></i> <?=e($a['location'])?> · <i class="bi bi-clock"></i> <?=$a['duration_minutes']?> min</div><h2 class="h4 fw-bold mt-2"><?=e($a['title'])?></h2><p class="text-secondary"><?=e($a['short_description'])?></p><div class="d-flex justify-content-between"><span class="badge rounded-pill text-bg-light"><?=e($a['level'])?></span><a href="/activite/<?=$a['id']?>" class="stretched-link text-decoration-none fw-semibold">Voir</a></div></div></article></div><?php endforeach; ?><?php if(!$activities): ?><div class="col-12"><div class="empty-state"><i class="bi bi-search"></i><h3>Aucune activité</h3><p>Essayez de modifier vos filtres.</p></div></div><?php endif; ?></div></main>